import re, numpy as np

def parse_pair(t, n):
 a=t.split(f'Demo pair {n} input (30x24):\n',1)[1].split(f'Demo pair {n} output (30x24):\n',1)[0]
 b=t.split(f'Demo pair {n} output (30x24):\n',1)[1].split('Same instance',1)[0]
 def mat(s):
  lines=[ln for ln in s.strip().splitlines() if re.fullmatch(r'[0-9 ]+',ln.strip())]
  return np.array([[int(x) for x in ln.split()] for ln in lines])
 return mat(a),mat(b)
