from collections import deque

def comps(mask):
 h,w=mask.shape; seen=np.zeros_like(mask,bool); out=[]
 for r,c in zip(*np.where(mask)):
  if seen[r,c]: continue
  q=[(r,c)]; seen[r,c]=1; pts=[]
  while q:
   rr,cc=q.pop(); pts.append((rr,cc))
   for nr,nc in [(rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)]:
    if 0<=nr<h and 0<=nc<w and mask[nr,nc] and not seen[nr,nc]: seen[nr,nc]=1;q.append((nr,nc))
  out.append(pts)
 return out

def predict(a, specs, top_end=10):
 pred=a.copy()
 # Clear template art above bands to background (assume top-left prevailing color)
 bg=int(a[0,0]); pred[:top_end,:]=bg
 for fill,edge,r0,r1 in specs: # inclusive content rows
  for pts in comps(a[:top_end,:]==fill):
   if not pts: continue
   bottom=max(r for r,c in pts); dy=r1-bottom
   for r,c in pts:
    rr=r+dy
    if r0<=rr<=r1: pred[rr,c]=edge
 return pred
